* Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
* @return the size of the message
*/
public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message by first writing its length
    int size = CodedOutputStream.computeUInt32SizeNoTag(message.getSerializedSize(schema));
    out.write(size);

    // Then serialize the message itself
    CodedOutputStream output = CodedOutputStream.newInstance(out, buffer);
    message.writeTo(output, schema);

    // Make sure the stream is flushed
    output.flush();

    return size;
}

