List<TimeRange> function (long start, long end) {
    // Calculate the number of time ranges that we need to split the range into
    long fetchDataDuration = FETCH_DATA_DURATION;
    long rangeSize = end - start;
    long numRanges = rangeSize / fetchDataDuration;
    // Round up the number of ranges if the last range would have more than 
    // `fetchDataDuration` data points
    if (rangeSize % fetchDataDuration != 0) {
         numRanges++;
    }

    // Create the time ranges and populate them with data
    List<TimeRange> timeRanges = new ArrayList<TimeRange>(numRanges);
    long remainingRange = end - start;
    long currentStart = start;
    while (remainingRange > 0) {
             long currentEnd = currentStart + Math.min(fetchDataDuration, remainingRange);
             timeRanges.add(new TimeRange(currentStart, currentEnd));
             remainingRange -= fetchDataDuration;
             currentStart += fetchDataDuration;
    }
    return timeRanges;
}

