    if (str == null) {
        return null;
    }

    // use a StringBuffer for better performance
    StringBuffer result = new StringBuffer();

    // the index of the current character
    int i = 0;

    // check every character in the string
    while (i < str.length()) {
        char c = str.charAt(i);

        // check for the escape character, backslash
        if (c == '\\') {
            // if escaped, then look at the next character
            if (i + 1 < str.length()) {
                char next = str.charAt(i + 1);

                if (next == '\'' || next == '"' || next == '\\' || next == 'n' || next == 'r' || next == 't' || next == 'b' || next == 'f') {
                    // escape character is consumed, so move on the next character
                    i++;
                }
            }
        }

