}

private static String javaCharset(String charset) {
    if (charset != null) {
        // Handle some commonly used aliases
        if (charset.equalsIgnoreCase("us-ascii")) {
            return "US-ASCII";
        } else if (charset.equalsIgnoreCase("utf-8")) {
            return "UTF-8";
        } else if (charset.equalsIgnoreCase("utf-16")) {
            return "UTF-16";
        } else if (charset.equalsIgnoreCase("utf-16le")) {
            return "UTF-16LE";
        } else if (charset.equalsIgnoreCase("utf-16be")) {
            return "UTF-16BE";
        }

        // Otherwise, use the Java character set API to map the name to a charset
        try {
            return java.nio.charset.Charset.forName(charset).name();
        } catch (Exception e) {
            // Fall back to using the MIME name if there is a problem
            return charset;
        }
    }
    return null;
}

public static String javaCharset(String charset) {
    // Check if the given charset is a valid Java charset
    if (Charset.isSupported(charset)) {
        return charset;
    }

    // Otherwise, try to map it to a Java charset using the MIME charset mapping
    Charset charsetFromMime = StandardCharsets.lookup(charset);
    if (charsetFromMime != null) {
        return charsetFromMime.name();
    }

    // If all else fails, use the default Java charset
    return StandardCharsets.ISO_8859_1.name();
}

