    // Initialize an empty graph path
    GraphPath<V, E> path = new GraphPath<>(graph);

    // Loop through the tour set
    for (E edge : tour) {
        // Get the start and end vertices of the edge
        V start = graph.getEdgeStart(edge);
        V end = graph.getEdgeEnd(edge);

        // Add the edge to the path
        path.addEdge(start, end, edge);
    }

