  GraphPath<V, E> path = graph.createPath(false, false);

  // Iterate over the edges in the set
  for (E edge : tour) {
    // Get the vertices of the edge
    V v1 = graph.getEdgeSource(edge);
    V v2 = graph.getEdgeTarget(edge);

    // Add the vertices to the graph path
    path.addVertex(v1);
    path.addVertex(v2);
  }

  // Return the graph path
  return path;
}

