private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the result list and the sum
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0L;

    // Iterate through the bounds list
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Get the current bound
        int bound = bounds.get(i);

        // Compute the suffix sum for the current bound
        int suffixBound = bound;
        for (int j = i - 1; j >= 0; j--) {
            suffixBound = Math.max(suffixBound, bounds.get(j));
            suffixSum.add(suffixBound);
        }

        // Add the suffix sum to the total sum
        totalSum += suffixBound;
    }

    // Return the computed suffix sum and the total sum
    return new Pair<>(suffixSum, totalSum);
}

