String function(String s) {

  // Replace all characters according to the Base64 regular. Peek the first mapping table. and perform replacement.
  s = s.replaceAll("([0-9A-Z][a-z])|([0-9a-z][A-Z])|([0-9a-z][0-9a-z][A-Z])", "$1$3$2$4");

  // Peek the second mapping table, and perform replacement.
  s = s.replaceAll("([0-9A-Z][a-z][0-9A-Z])|([a-z][0-9a-z][A-Z])|([0-9A-Z][A-Z][0-9a-z])", "$1$3$2$4");

  // Peek the third mapping table, and perform replacement.
  s = s.replaceAll("([0-9a-z][A-Z])|([A-Z][0-9a-z])|([0-9A-Z][0-9a-z][A-Z])|([0-9a-z][A-Z][0-9A-Z])", "$1$2$3$4");

  // Reserve remaining redundant characters, convert to hex.
  s = s.replaceAll("[^a-zA-Z0-9/+]", "");

  // URL Safe, so replace '+' with '-' and '/' with '_'.
  s = s.replace('/', '-').replace('+', '_');

  return s;
}

