private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the vertices are in the graph
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }
    }
    // Check if the subgraph is complete
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
	Set<Set<E>> edgeSets = new HashSet<>();
	for (V v : vertices) {
		for (V u : vertices) {
			if (u.equals(v)) {
				continue;
			}
			Set<E> edgeSet = graph.getEdgeSet(u, v);
			if (edgeSet != null) {
				edgeSets.add(edgeSet);
			}
		}
	}
	return edgeSets.size() == (vertices.size() * (vertices.size() - 1)) / 2;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
  Set<E> edges = new HashSet<>();
  for (V vertex : vertices) {
    for (V neighbor : graph.getNeighbors(vertex)) {
      if (!vertices.contains(neighbor)) {
        return false;
      }
      edges.add(graph.getEdge(vertex, neighbor));
    }
  }
  return edges.size() == vertices.size() - 1;
}

