public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
      return null;
    }

    var pathSegments = path.split("/");
    var relativePathSegments = relativePath.split("/");
    var builder = new StringBuilder();

    for (int i = 0; i < pathSegments.length && i < relativePathSegments.length; i++) {
      var pathSegment = pathSegments[i];
      var relativePathSegment = relativePathSegments[i];

      if (relativePathSegment.equals(".")) {
        // do nothing
      } else if (relativePathSegment.equals("..")) {
        if (builder.length() > 0) {
          builder.delete(builder.length() - 1, builder.length());
        }
      } else {
        if (builder.length() > 0) {
          builder.append("/");
        }
        builder.append(relativePathSegment);
      }
    }

    if (builder.length() == 0) {
      return "/";
    }

    return builder.toString();
  }

