public static String applyRelativePath(String path, String relativePath) {
    //Split the path and relative path into individual segments
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    //Create a new path string builder
    StringBuilder newPath = new StringBuilder();

    //Iterate through the relative path parts
    for (String part : relativePathParts) {
        //If the part is "..", remove the last path part from the new path
        if (part.equals("..")) {
            newPath.deleteCharAt(newPath.lastIndexOf("/"));
        }
        //Otherwise, append the part to the new path
        else {
            newPath.append(part).append("/");
        }
    }

    //If the new path is empty, return the root path
    if (newPath.length() == 0) {
        return "/";
    }

    //Otherwise, return the new path
    return newPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {

    // Check if the relative path is absolute
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // If the relative path is not absolute, get the directory name from the path
    String dirName = new File(path).getParent();

    // Append the relative path to the directory name
    return dirName + "/" + relativePath;
}

