public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
 List<ThreadSnapshot> snapshots = new ArrayList<>();

 // Open the file and create a new reader
 try ( BufferedReader reader = new BufferedReader(new FileReader(file))) {

  // Loop through the time ranges and load the snapshots
  for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
   long startTime = timeRange.getStartTime();
   long endTime = timeRange.getEndTime();

   // Load the snapshot for the given time range
   ThreadSnapshot snapshot = new ThreadSnapshot(startTime, endTime);

   // Read the snapshot data from the file
   String line;
   while ((line = reader.readLine()) != null) {
    if (line.startsWith("Thread ")) {
     int threadId = Integer.parseInt(line.split(" ")[2]);
     snapshot.addThread(threadId);
    } else if (line.startsWith("Load time")) {
     snapshot.setLoadTime(Long.parseLong(line.split(" ")[4]));
    } else if (line.startsWith("Total run time")) {
     snapshot.setTotalRunTime(Long.parseLong(line.split(" ")[4]));
    }
   }

   // Add the loaded snapshot to the list
   snapshots.add(snapshot);
  }

 } catch (IOException e) {
  throw new IOException("Failed to read thread snapshots from file", e);
 }

 return snapshots;
